INSERT INTO vault_record_grant (account_id,origin,vault_id,collection_id,record_id,kind,record_revision,ciphertext_sha256,key_generation,owner_key_revision,recipient_service,purpose,envelope_id,version,status,expires_at,updated_at) SELECT account_id,origin,vault_id,collection_id,record_id,kind,record_revision,ciphertext_sha256,key_generation,owner_key_revision,recipient_service,purpose,envelope_id,1,'active',unixepoch()+?3,unixepoch() FROM vault_record_recipient_envelope WHERE account_id=?1 AND envelope_id=?2 ON CONFLICT(account_id,vault_id,collection_id,record_id,recipient_service,purpose) DO UPDATE SET origin=excluded.origin,kind=excluded.kind,record_revision=excluded.record_revision,ciphertext_sha256=excluded.ciphertext_sha256,key_generation=excluded.key_generation,owner_key_revision=excluded.owner_key_revision,envelope_id=excluded.envelope_id,version=vault_record_grant.version+1,status='active',expires_at=excluded.expires_at,updated_at=excluded.updated_at
